/* Wordmark KASUARI SIGAP (dipakai halaman pasien, login perawat, poster, kartu QR).
   opt: {s: skala (1 = landing), sub: tampilkan kepanjangan} */
function wordmarkHtml(opt){
  opt = opt || {}; var s = opt.s || 1;
  return '<div class="wordmark sigap" style="font-size:' + s + 'rem">' +
    '<div class="w1">KASUARI</div><div class="w2">SIGAP</div>' +
    (opt.sub === false ? '' : '<div class="w4">Sistem Informasi Gejala dan <br>Arahan Perawatan</div>') +
    '<div class="hl">EKSTRAVASASI</div></div>';
}
/* Markdown ringan untuk jawaban AI: **tebal**, poin "- ", judul "#". Di-escape dulu (aman dari HTML). */
function mdLite(t){
  var e = String(t == null ? '' : t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
  return e.split('\n').map(function(l){
    var h = l.match(/^\s*#{1,4}\s+(.*)$/); if (h) return '<b class="h">' + h[1].replace(/\*\*/g, '') + '</b>';
    var hb = l.match(/^\s*\*\*([^*]+)\*\*\s*:?\s*$/); if (hb) return '<b class="h">' + hb[1] + '</b>';
    var li = l.match(/^\s*(?:[-*•]|\d+[.)])\s+(.*)$/); if (li) return '<span class="li">' + li[1] + '</span>';
    return l;
  }).join('<br>').replace(/\*\*(.+?)\*\*/g, '<b>$1</b>')
    .replace(/(https?:\/\/[^\s<"]+?)([.,;:!?)]*)(?=\s|<|$)/g, function(m, u, tail){ return '<a href="' + u + '" target="_blank" rel="noopener" style="color:var(--teal-700);font-weight:700;word-break:break-all">' + u + '</a>' + tail; })
    .replace(/<\/span>(<br>)+/g, '</span>').replace(/(<br>)+(<b class="h">)/g, '$2').replace(/(<b class="h">[^<]*<\/b>)(<br>)+/g, '$1').replace(/^(<br>)+/, '');
}
function refsHtml(src){
  src = (src || []).filter(function(s){ return s && s.title; });
  if (!src.length) return '';
  return '<div class="refs"><b>Rujukan</b>' + src.map(function(s, i){ var t = String(s.title).replace(/</g, '&lt;'); return /^https:\/\//i.test(String(s.uri || '')) ? '<a href="' + String(s.uri).replace(/"/g, '&quot;') + '" target="_blank" rel="noopener">' + (i + 1) + '. ' + t + '</a>' : '<span>' + (i + 1) + '. ' + t + '</span>'; }).join('') + '</div>';
}
function icon(n, cls) {
  return '<svg class="ic ' + (cls || '') + '" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' + (ICON[n] || '') + '</svg>';
}
